BASE=Path(__file__).resolve().parents[1];WEB=BASE/'GitHub';CSS=runtime_styles(WEB)
SCRIPTS=['logical-move.js','reasoning-view.js','reasoning-presentation.js','pedagogy-metadata.js','nonogram-logic.js','difficulty-rating.js','nonogram-difficulty.js','session-core.js','game-session-adapters.js','game-ui-adapters.js','nonogram-reasoning-presentation.js','nonogram-pedagogy.js','nonogram-ui.js']
