with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=browser.new_context(viewport={'width':390,'height':844},locale='fr-FR',is_mobile=True,has_touch=True);page=ctx.new_page();setup(page)
    before=page.evaluate("""()=>({sourceUnchanged:JSON.stringify(source)===sourceBefore,workState:walk.work.state.map(r=>[...r]),nodes:Object.keys(walk.work.moveHistory.nodes).length,moves:walk.moves.length,levels:preview.levels.map(x=>x.id),technique:preview.presentation.technique,target:document.querySelectorAll('.ng-focus-target').length,premise:document.querySelectorAll('.ng-focus-premise').length,context:document.querySelectorAll('.ng-focus-context').length,text:document.querySelector('#tutorText').textContent,hidden:JSON.stringify(preview).includes('solutionGrid')||JSON.stringify(preview).includes('validationState')})""")
    assert before['sourceUnchanged'] and before['nodes']==1 and before['moves']==0 and all(v==0 for row in before['workState'] for v in row),before;assert before['levels']==['where','technique','why','move'] and before['technique']=='N_EXACT_FIT' and before['target']==5 and before['premise']>=1 and before['context']>=1 and before['text'].strip() and not before['hidden'],before
